using System;
using System.Data;
using System.Web.UI;
using System.Web.UI.WebControls;
using DCore;
using PollObject;

namespace InformationWeb.Pages.Poll2
{
    public partial class AnswerList : PageBase
    {
        private const int FIXED_POLL_PART_ID = 56;

        #region Properties

        protected DCore.SessionUser CurrentUser
        {
            get { return Session[Globals.USER] as DCore.SessionUser; }
        }

        protected CommonControls.MessageBox.MessageBox MsgBox
        {
            get
            {
                if (Master == null)
                    return null;

                Control objControl = FindControlRecursive(Master, "MsgBox");
                return objControl as CommonControls.MessageBox.MessageBox;
            }
        }

        #endregion

        #region Page Events

        protected void Page_Load(object sender, EventArgs e)
        {
            if (CurrentUser == null)
            {
                Response.Redirect("~/dang-nhap.html");
                return;
            }

            ApplyFixedPollPartState();

            if (!IsPostBack)
            {
                BindDataTypeDropdown();
                BindQuestionDropdowns();
                BindGrid();
            }
        }

        #endregion

        #region Helpers

        private Control FindControlRecursive(Control objRoot, string strId)
        {
            if (objRoot == null)
                return null;

            if (objRoot.ID == strId)
                return objRoot;

            foreach (Control objChild in objRoot.Controls)
            {
                Control objFound = FindControlRecursive(objChild, strId);
                if (objFound != null)
                    return objFound;
            }

            return null;
        }

        private int GetAnswerID()
        {
            int intAnswerID = 0;
            int.TryParse(hidAnswerID.Value, out intAnswerID);
            return intAnswerID;
        }

        private int GetSelectedQuestionFilterID()
        {
            int intQuestionID = 0;
            int.TryParse(ddlQuestionFilter.SelectedValue, out intQuestionID);
            return intQuestionID;
        }

        private int GetSelectedQuestionEditID()
        {
            int intQuestionID = 0;
            int.TryParse(ddlQuestionEdit.SelectedValue, out intQuestionID);
            return intQuestionID;
        }

        private int GetSelectedDataTypeID()
        {
            int intDataTypeID = 0;
            int.TryParse(ddlDataTypeID.SelectedValue, out intDataTypeID);
            return intDataTypeID;
        }

        private decimal GetMarkValue()
        {
            decimal decMark = 0;
            decimal.TryParse(txtMark.Text.Trim(), out decMark);
            return decMark;
        }

        private void ApplyFixedPollPartState()
        {
            txtPollPartID.Text = FIXED_POLL_PART_ID.ToString();
        }

        private POL_Plan CreateDataObject()
        {
            return new POL_Plan();
        }

        private void BindDataTypeDropdown()
        {
            ddlDataTypeID.Items.Clear();
            ddlDataTypeID.Items.Add(new ListItem("0 - Check chọn", "0"));
            ddlDataTypeID.Items.Add(new ListItem("1 - Nhập text (1 dòng)", "1"));
            ddlDataTypeID.Items.Add(new ListItem("2 - Nhập text (nhiều dòng)", "2"));
        }

        private void BindQuestionDropdowns()
        {
            try
            {
                POL_Plan obj = CreateDataObject();
                DataTable dtb = obj.GetDataTable("POL_Answer_GetQuestionList", "@PollPartID", FIXED_POLL_PART_ID);

                ddlQuestionFilter.Items.Clear();
                ddlQuestionFilter.Items.Add(new ListItem("--- Tất cả câu hỏi ---", "0"));

                ddlQuestionEdit.Items.Clear();

                if (dtb != null)
                {
                    foreach (DataRow dr in dtb.Rows)
                    {
                        string strQuestionID = dr["QuestionID"].ToString();
                        string strQuestionCode = dr["QuestionCode"].ToString();
                        string strQuestionName = dr["QuestionName"].ToString();
                        string strDisplay = String.Format("{0} - {1}", strQuestionCode, strQuestionName);
                        if (strDisplay.Length > 120)
                            strDisplay = strDisplay.Substring(0, 120) + "...";

                        ddlQuestionFilter.Items.Add(new ListItem(strDisplay, strQuestionID));
                        ddlQuestionEdit.Items.Add(new ListItem(strDisplay, strQuestionID));
                    }
                }

                if (ddlQuestionEdit.Items.Count == 0)
                    ddlQuestionEdit.Items.Add(new ListItem("--- Chưa có câu hỏi ---", "0"));
            }
            catch (Exception)
            {
                ShowError("Không tải được danh sách câu hỏi. Kiểm tra script POL_Answer_Manage.sql trên DB.");
            }
        }

        private void SelectQuestionEditValue(string strQuestionID)
        {
            ListItem objItem = ddlQuestionEdit.Items.FindByValue(strQuestionID);
            if (objItem != null)
                ddlQuestionEdit.SelectedValue = strQuestionID;
            else if (ddlQuestionEdit.Items.Count > 0)
                ddlQuestionEdit.SelectedIndex = 0;
        }

        private void SelectDataTypeValue(string strDataTypeID)
        {
            ListItem objItem = ddlDataTypeID.Items.FindByValue(strDataTypeID);
            if (objItem != null)
                ddlDataTypeID.SelectedValue = strDataTypeID;
            else
                ddlDataTypeID.SelectedIndex = 0;
        }

        #endregion

        #region Data

        private void BindGrid()
        {
            try
            {
                POL_Plan obj = CreateDataObject();
                int intQuestionID = GetSelectedQuestionFilterID();
                object objQuestionParam = intQuestionID > 0 ? (object)intQuestionID : DBNull.Value;

                DataTable dtb = obj.GetDataTable("POL_Answer_SearchForManage",
                    "@PollPartID", FIXED_POLL_PART_ID,
                    "@QuestionID", objQuestionParam,
                    "@KeyWord", txtSearch.Text.Trim());

                grvData.DataSource = dtb;
                grvData.DataBind();
                udpList.Update();
            }
            catch (Exception)
            {
                ShowError("Không tải được danh sách đáp án. Kiểm tra đã chạy script POL_Answer_Manage.sql chưa.");
            }
        }

        private void ResetEditForm()
        {
            hidAnswerID.Value = "0";
            txtAnswerCode.Text = "";
            txtAnswerName.Text = "";
            txtMark.Text = "0";
            txtFixFromColumn.Text = "";
            txtDescription.Text = "";
            txtOrderIndex.Text = "";
            chkIsActived.Checked = true;
            lblTitle.Text = "Chi tiết đáp án";

            if (ddlQuestionEdit.Items.Count > 0)
            {
                int intQuestionID = GetSelectedQuestionFilterID();
                if (intQuestionID > 0)
                    SelectQuestionEditValue(intQuestionID.ToString());
                else
                    ddlQuestionEdit.SelectedIndex = 0;
            }

            ddlDataTypeID.SelectedIndex = 0;
        }

        private void LoadEditForm(int intAnswerID)
        {
            ResetEditForm();

            if (intAnswerID > 0)
            {
                POL_Plan obj = CreateDataObject();
                DataTable dtb = obj.GetDataTable("POL_Answer_Get", "@AnswerID", intAnswerID);

                if (dtb == null || dtb.Rows.Count == 0)
                {
                    ShowWarning("Không tìm thấy đáp án!");
                    return;
                }

                DataRow dr = dtb.Rows[0];
                int intPollPartID = 0;
                int.TryParse(dr["PollPartID"].ToString(), out intPollPartID);
                if (intPollPartID != FIXED_POLL_PART_ID)
                {
                    ShowWarning("Đáp án không thuộc phần khảo sát cố định!");
                    udpEdit.Update();
                    return;
                }

                hidAnswerID.Value = dr["AnswerID"].ToString();
                txtAnswerCode.Text = dr["AnswerCode"].ToString();
                txtAnswerName.Text = dr["AnswerName"].ToString();
                txtOrderIndex.Text = dr["OrderIndex"].ToString();
                txtMark.Text = dr["Mark"].ToString();
                txtFixFromColumn.Text = dr["FixFromColumn"].ToString();
                txtDescription.Text = dr["Description"].ToString();
                chkIsActived.Checked = Convert.ToBoolean(dr["IsActived"]);
                SelectQuestionEditValue(dr["QuestionID"].ToString());
                SelectDataTypeValue(dr["DataTypeID"].ToString());
                lblTitle.Text = "Cập nhật đáp án";
            }
            else
            {
                lblTitle.Text = "Thêm đáp án mới";
            }

            udpEdit.Update();
            ShowModal();
        }

        private void ShowModal()
        {
            string strKey = String.Format("_OpenPollAnswerModal_{0}", DateTime.Now.Ticks);
            ScriptManager.RegisterStartupScript(Page, Page.GetType(), strKey, "PollAnswer_ShowModal();", true);
        }

        private void HideModal()
        {
            string strKey = String.Format("_ClosePollAnswerModal_{0}", DateTime.Now.Ticks);
            ScriptManager.RegisterStartupScript(Page, Page.GetType(), strKey, "PollAnswer_HideModal();", true);
        }

        private bool ValidateForm()
        {
            if (GetSelectedQuestionEditID() <= 0)
            {
                ShowWarning("Vui lòng chọn câu hỏi (QuestionID)!");
                return false;
            }

            if (txtAnswerCode.Text.Trim() == "")
            {
                ShowWarning("Vui lòng nhập mã đáp án (AnswerCode)!");
                return false;
            }

            if (txtAnswerName.Text.Trim() == "")
            {
                ShowWarning("Vui lòng nhập nội dung đáp án (AnswerName)!");
                return false;
            }

            return true;
        }

        private bool SaveData()
        {
            POL_Plan obj = CreateDataObject();
            int intAnswerID = GetAnswerID();
            string strUserName = CurrentUser != null ? CurrentUser.UserName : "system";

            try
            {
                if (intAnswerID <= 0)
                {
                    DataTable dtb = obj.GetDataTable("POL_Answer_Add",
                        "@AnswerCode", txtAnswerCode.Text.Trim(),
                        "@AnswerName", txtAnswerName.Text.Trim(),
                        "@QuestionID", GetSelectedQuestionEditID(),
                        "@DataTypeID", GetSelectedDataTypeID(),
                        "@Mark", GetMarkValue(),
                        "@FixFromColumn", txtFixFromColumn.Text.Trim(),
                        "@Description", txtDescription.Text.Trim(),
                        "@IsActived", chkIsActived.Checked,
                        "@CreatedUser", strUserName);

                    if (dtb == null || dtb.Rows.Count == 0)
                    {
                        ShowError("Không thêm được đáp án. Vui lòng thử lại!");
                        return false;
                    }

                    txtOrderIndex.Text = dtb.Rows[0]["OrderIndex"].ToString();
                }
                else
                {
                    DataTable dtb = obj.GetDataTable("POL_Answer_Update",
                        "@AnswerID", intAnswerID,
                        "@AnswerCode", txtAnswerCode.Text.Trim(),
                        "@AnswerName", txtAnswerName.Text.Trim(),
                        "@QuestionID", GetSelectedQuestionEditID(),
                        "@DataTypeID", GetSelectedDataTypeID(),
                        "@Mark", GetMarkValue(),
                        "@FixFromColumn", txtFixFromColumn.Text.Trim(),
                        "@Description", txtDescription.Text.Trim(),
                        "@IsActived", chkIsActived.Checked,
                        "@UpdatedUser", strUserName);

                    if (dtb == null || dtb.Rows.Count == 0 || Convert.ToInt32(dtb.Rows[0]["AffectedRows"]) <= 0)
                    {
                        ShowError("Không cập nhật được đáp án. Vui lòng thử lại!");
                        return false;
                    }
                }

                return true;
            }
            catch (Exception)
            {
                ShowError("Lỗi lưu dữ liệu. Vui lòng thử lại sau!");
                return false;
            }
        }

        private void DeleteAnswer(int intAnswerID)
        {
            try
            {
                POL_Plan obj = CreateDataObject();
                DataTable dtb = obj.GetDataTable("POL_Answer_Delete", "@AnswerID", intAnswerID);

                if (dtb == null || dtb.Rows.Count == 0 || Convert.ToInt32(dtb.Rows[0]["AffectedRows"]) <= 0)
                {
                    ShowWarning("Không xóa được đáp án!");
                    return;
                }

                BindGrid();
            }
            catch (Exception)
            {
                ShowError("Lỗi xóa dữ liệu. Vui lòng thử lại sau!");
            }
        }

        private void ShowWarning(string strMessage)
        {
            if (MsgBox != null)
                MsgBox.ShowWarning(strMessage);
        }

        private void ShowError(string strMessage)
        {
            if (MsgBox != null)
                MsgBox.ShowError(strMessage);
        }

        #endregion

        #region Control Events

        protected void btnSearch_Click(object sender, EventArgs e)
        {
            ApplyFixedPollPartState();
            ResetEditForm();
            udpEdit.Update();
            HideModal();
            BindGrid();
        }

        protected void btnAddNew_Click(object sender, EventArgs e)
        {
            LoadEditForm(0);
        }

        protected void grvData_RowCommand(object sender, GridViewCommandEventArgs e)
        {
            int intAnswerID = Convert.ToInt32(e.CommandArgument);

            if (e.CommandName == "EditItem")
            {
                LoadEditForm(intAnswerID);
            }
            else if (e.CommandName == "DeleteItem")
            {
                DeleteAnswer(intAnswerID);
            }
        }

        protected void btnSave_Click(object sender, EventArgs e)
        {
            try
            {
                if (!ValidateForm())
                {
                    udpEdit.Update();
                    ShowModal();
                    return;
                }

                if (SaveData())
                {
                    ResetEditForm();
                    udpEdit.Update();
                    HideModal();
                    BindGrid();
                }
                else
                {
                    udpEdit.Update();
                    ShowModal();
                }
            }
            catch (Exception)
            {
                ShowError("Lỗi xử lý khi lưu. Kiểm tra script POL_Answer_Manage.sql trên DB.");
                udpEdit.Update();
                ShowModal();
            }
        }

        protected void btnCancel_Click(object sender, EventArgs e)
        {
            ResetEditForm();
            udpEdit.Update();
            HideModal();
        }

        #endregion
    }
}

