private void SelectDataTypeValue(string strDataTypeID)
{
    ListItem objItem = ddlDataTypeID.Items.FindByValue(strDataTypeID);
    if (objItem != null)
        ddlDataTypeID.SelectedValue = strDataTypeID;
    else
        ddlDataTypeID.SelectedIndex = 0;
}

private DataTable GetQuestionDataTable()
{
    POL_Plan obj = CreateDataObject();
    return obj.GetDataTable("POL_Answer_GetQuestionList", "@PollPartID", FIXED_POLL_PART_ID);
}

private void BindGridQuestionDropdown(DropDownList ddl, string strSelectedQuestionID)
{
    ddl.Items.Clear();
    DataTable dtb = GetQuestionDataTable();

    if (dtb != null)
    {
        foreach (DataRow dr in dtb.Rows)
        {
            string strQuestionID = dr["QuestionID"].ToString();
            string strQuestionCode = dr["QuestionCode"].ToString();
            string strQuestionName = dr["QuestionName"].ToString();
            string strDisplay = String.Format("{0} - {1}", strQuestionCode, strQuestionName);
            if (strDisplay.Length > 80)
                strDisplay = strDisplay.Substring(0, 80) + "...";

            ddl.Items.Add(new ListItem(strDisplay, strQuestionID));
        }
    }

    if (ddl.Items.Count == 0)
    {
        ddl.Items.Add(new ListItem("--- Chưa có câu hỏi ---", "0"));
    }
    else
    {
        ListItem objItem = ddl.Items.FindByValue(strSelectedQuestionID);
        if (objItem != null)
            ddl.SelectedValue = strSelectedQuestionID;
        else
            ddl.SelectedIndex = 0;
    }
}

private void BindGridDataTypeDropdown(DropDownList ddl, string strSelectedDataTypeID)
{
    ddl.Items.Clear();
    ddl.Items.Add(new ListItem("0-Check", "0"));
    ddl.Items.Add(new ListItem("1-Text", "1"));
    ddl.Items.Add(new ListItem("2-Multi", "2"));

    ListItem objItem = ddl.Items.FindByValue(strSelectedDataTypeID);
    if (objItem != null)
        ddl.SelectedValue = strSelectedDataTypeID;
    else
        ddl.SelectedIndex = 0;
}

private GridViewRow FindGridRowByAnswerID(int intAnswerID)
{
    foreach (GridViewRow row in grvData.Rows)
    {
        if (row.RowType != DataControlRowType.DataRow)
            continue;

        int intRowAnswerID = 0;
        int.TryParse(grvData.DataKeys[row.RowIndex].Value.ToString(), out intRowAnswerID);
        if (intRowAnswerID == intAnswerID)
            return row;
    }

    return null;
}

private bool GetGridRowValues(GridViewRow row, out int intAnswerID, out string strAnswerCode,
    out string strAnswerName, out int intQuestionID, out int intDataTypeID, out decimal decMark,
    out string strFixFromColumn, out string strDescription, out bool bolIsActived, out string strError)
{
    intAnswerID = 0;
    strAnswerCode = "";
    strAnswerName = "";
    intQuestionID = 0;
    intDataTypeID = 0;
    decMark = 0;
    strFixFromColumn = "";
    strDescription = "";
    bolIsActived = true;
    strError = "";

    if (row == null)
    {
        strError = "Không tìm thấy dòng trên lưới!";
        return false;
    }

    int.TryParse(grvData.DataKeys[row.RowIndex].Value.ToString(), out intAnswerID);

    TextBox txtGridAnswerCode = row.FindControl("txtGridAnswerCode") as TextBox;
    TextBox txtGridAnswerName = row.FindControl("txtGridAnswerName") as TextBox;
    TextBox txtGridMark = row.FindControl("txtGridMark") as TextBox;
    DropDownList ddlGridQuestion = row.FindControl("ddlGridQuestion") as DropDownList;
    DropDownList ddlGridDataType = row.FindControl("ddlGridDataType") as DropDownList;
    HiddenField hidGridFixFromColumn = row.FindControl("hidGridFixFromColumn") as HiddenField;
    HiddenField hidGridDescription = row.FindControl("hidGridDescription") as HiddenField;
    HiddenField hidGridIsActived = row.FindControl("hidGridIsActived") as HiddenField;

    if (txtGridAnswerCode != null)
        strAnswerCode = txtGridAnswerCode.Text.Trim();
    if (txtGridAnswerName != null)
        strAnswerName = txtGridAnswerName.Text.Trim();
    if (txtGridMark != null)
        decimal.TryParse(txtGridMark.Text.Trim(), out decMark);
    if (ddlGridQuestion != null)
        int.TryParse(ddlGridQuestion.SelectedValue, out intQuestionID);
    if (ddlGridDataType != null)
        int.TryParse(ddlGridDataType.SelectedValue, out intDataTypeID);
    if (hidGridFixFromColumn != null)
        strFixFromColumn = hidGridFixFromColumn.Value;
    if (hidGridDescription != null)
        strDescription = hidGridDescription.Value;
    if (hidGridIsActived != null)
        bool.TryParse(hidGridIsActived.Value, out bolIsActived);

    if (intQuestionID <= 0)
    {
        strError = String.Format("Dòng mã {0}: vui lòng chọn câu hỏi!", intAnswerID);
        return false;
    }

    if (strAnswerCode == "")
    {
        strError = String.Format("Dòng mã {0}: vui lòng nhập mã đáp án!", intAnswerID);
        return false;
    }

    if (strAnswerName == "")
    {
        strError = String.Format("Dòng mã {0}: vui lòng nhập nội dung đáp án!", intAnswerID);
        return false;
    }

    return true;
}

private bool UpdateAnswerRow(int intAnswerID, string strAnswerCode, string strAnswerName, int intQuestionID,
