private decimal ParseMarkValue(string strText)
{
    decimal decMark = 0;
    if (string.IsNullOrWhiteSpace(strText))
        return 0;

    string strValue = strText.Trim().Replace(',', '.');

    if (!decimal.TryParse(strValue, NumberStyles.Number, CultureInfo.InvariantCulture, out decMark))
        decimal.TryParse(strText.Trim(), NumberStyles.Number, CultureInfo.CurrentCulture, out decMark);

    return decMark;
}

private string FormatMarkForGrid(object objMark)
{
    if (objMark == null || objMark == DBNull.Value)
        return "0";

    decimal decMark = Convert.ToDecimal(objMark);
    return decMark.ToString("0.##", CultureInfo.InvariantCulture);
}

