private void PrepareGridRowsForPostback()
{
    foreach (GridViewRow row in grvData.Rows)
    {
        if (row.RowType != DataControlRowType.DataRow)
            continue;

        DropDownList ddlGridQuestion = row.FindControl("ddlGridQuestion") as DropDownList;
        DropDownList ddlGridDataType = row.FindControl("ddlGridDataType") as DropDownList;
        HiddenField hidGridQuestionID = row.FindControl("hidGridQuestionID") as HiddenField;
        HiddenField hidGridDataTypeID = row.FindControl("hidGridDataTypeID") as HiddenField;
        string strQuestionID = GetPostedControlValue(hidGridQuestionID);
        string strDataTypeID = GetPostedControlValue(hidGridDataTypeID);

        if (ddlGridQuestion != null && ddlGridQuestion.Items.Count == 0)
        {
            if (strQuestionID == "")
                strQuestionID = hidGridQuestionID != null ? hidGridQuestionID.Value : "0";
            BindGridQuestionDropdown(ddlGridQuestion, strQuestionID);
        }

        if (ddlGridDataType != null && ddlGridDataType.Items.Count == 0)
        {
            if (strDataTypeID == "")
                strDataTypeID = hidGridDataTypeID != null ? hidGridDataTypeID.Value : "0";
            BindGridDataTypeDropdown(ddlGridDataType, strDataTypeID);
        }
    }
}

private string GetPostedControlValue(Control ctrl)
{
    if (ctrl == null)
        return "";

    string strFormValue = Request.Form[ctrl.UniqueID];
    if (strFormValue != null)
        return strFormValue;

    TextBox txtControl = ctrl as TextBox;
    if (txtControl != null)
        return txtControl.Text;

    DropDownList ddlControl = ctrl as DropDownList;
    if (ddlControl != null)
        return ddlControl.SelectedValue;

    HiddenField hidControl = ctrl as HiddenField;
    if (hidControl != null)
        return hidControl.Value;

    return "";
}

private bool ParseBoolValue(string strValue, bool bolDefault)
{
    if (string.IsNullOrWhiteSpace(strValue))
        return bolDefault;

    if (strValue == "1")
        return true;

    if (strValue == "0")
        return false;

    bool bolResult = bolDefault;
    bool.TryParse(strValue, out bolResult);
    return bolResult;
}

