private bool GetGridRowValues(GridViewRow row, out int intAnswerID, out string strAnswerCode,
    out string strAnswerName, out int intQuestionID, out int intDataTypeID, out decimal decMark,
    out string strFixFromColumn, out string strDescription, out bool bolIsActived, out string strError)
{
    intAnswerID = 0;
    strAnswerCode = "";
    strAnswerName = "";
    intQuestionID = 0;
    intDataTypeID = 0;
    decMark = 0;
    strFixFromColumn = "";
    strDescription = "";
    bolIsActived = true;
    strError = "";

    if (row == null)
    {
        strError = "Không tìm thấy dòng trên lưới!";
        return false;
    }

    int.TryParse(grvData.DataKeys[row.RowIndex].Value.ToString(), out intAnswerID);
    if (intAnswerID <= 0)
    {
        strError = "Không xác định được mã đáp án trên lưới!";
        return false;
    }

    TextBox txtGridAnswerCode = row.FindControl("txtGridAnswerCode") as TextBox;
    TextBox txtGridAnswerName = row.FindControl("txtGridAnswerName") as TextBox;
    TextBox txtGridMark = row.FindControl("txtGridMark") as TextBox;
    DropDownList ddlGridQuestion = row.FindControl("ddlGridQuestion") as DropDownList;
    DropDownList ddlGridDataType = row.FindControl("ddlGridDataType") as DropDownList;
    HiddenField hidGridQuestionID = row.FindControl("hidGridQuestionID") as HiddenField;
    HiddenField hidGridDataTypeID = row.FindControl("hidGridDataTypeID") as HiddenField;
    HiddenField hidGridFixFromColumn = row.FindControl("hidGridFixFromColumn") as HiddenField;
    HiddenField hidGridDescription = row.FindControl("hidGridDescription") as HiddenField;
    HiddenField hidGridIsActived = row.FindControl("hidGridIsActived") as HiddenField;

    strAnswerCode = GetPostedControlValue(txtGridAnswerCode).Trim();
    strAnswerName = GetPostedControlValue(txtGridAnswerName).Trim();
    decMark = ParseMarkValue(GetPostedControlValue(txtGridMark));

    string strPostedQuestionID = GetPostedControlValue(ddlGridQuestion);
    if (strPostedQuestionID == "" || strPostedQuestionID == "0")
        strPostedQuestionID = GetPostedControlValue(hidGridQuestionID);
    int.TryParse(strPostedQuestionID, out intQuestionID);

    string strPostedDataTypeID = GetPostedControlValue(ddlGridDataType);
    if (strPostedDataTypeID == "")
        strPostedDataTypeID = GetPostedControlValue(hidGridDataTypeID);
    int.TryParse(strPostedDataTypeID, out intDataTypeID);

