private void SaveAllGridRows()
{
    if (grvData.Rows.Count == 0)
    {
        ShowWarning("Không có dữ liệu để cập nhật!");
        return;
    }

    int intSuccessCount = 0;
    int intFailCount = 0;
    int intSkippedCount = 0;

    foreach (GridViewRow row in grvData.Rows)
    {
        if (row.RowType != DataControlRowType.DataRow)
            continue;

        if (!IsGridRowChanged(row))
        {
            intSkippedCount++;
            continue;
        }

        if (SaveGridRow(row, false, false))
            intSuccessCount++;
        else
            intFailCount++;
    }

    BindGrid();

    if (intSuccessCount == 0 && intFailCount == 0)
    {
        ShowWarning("Không có dòng nào thay đổi để lưu!");
        return;
    }

    if (intFailCount == 0)
        ShowWarning(String.Format("Đã lưu {0} dòng đã sửa.", intSuccessCount));
    else
        ShowWarning(String.Format("Lưu thành công {0} dòng, thất bại {1} dòng.", intSuccessCount, intFailCount));
}

