private string GetGridRowChangedFieldNames(GridViewRow row)
{
    if (row == null)
        return "";

    HiddenField hidOrigAnswerCode = row.FindControl("hidOrigAnswerCode") as HiddenField;
    HiddenField hidOrigAnswerName = row.FindControl("hidOrigAnswerName") as HiddenField;
    HiddenField hidOrigQuestionID = row.FindControl("hidOrigQuestionID") as HiddenField;
    HiddenField hidOrigMark = row.FindControl("hidOrigMark") as HiddenField;
    TextBox txtGridAnswerCode = row.FindControl("txtGridAnswerCode") as TextBox;
    TextBox txtGridAnswerName = row.FindControl("txtGridAnswerName") as TextBox;
    TextBox txtGridMark = row.FindControl("txtGridMark") as TextBox;
    DropDownList ddlGridQuestion = row.FindControl("ddlGridQuestion") as DropDownList;

    string strOrigCode = hidOrigAnswerCode != null ? hidOrigAnswerCode.Value : "";
    string strOrigName = hidOrigAnswerName != null ? hidOrigAnswerName.Value : "";
    string strOrigQuestionID = hidOrigQuestionID != null ? hidOrigQuestionID.Value : "";
    string strOrigMark = hidOrigMark != null ? hidOrigMark.Value : "0";

    string strCurCode = GetPostedControlValue(txtGridAnswerCode).Trim();
    string strCurName = GetPostedControlValue(txtGridAnswerName).Trim();
    string strCurQuestionID = GetPostedControlValue(ddlGridQuestion);
    if (strCurQuestionID == "" || strCurQuestionID == "0")
    {
        HiddenField hidGridQuestionID = row.FindControl("hidGridQuestionID") as HiddenField;
        strCurQuestionID = GetPostedControlValue(hidGridQuestionID);
    }
    string strCurMark = ParseMarkValue(GetPostedControlValue(txtGridMark)).ToString("0.##", CultureInfo.InvariantCulture);
    string strOrigMarkNorm = ParseMarkValue(strOrigMark).ToString("0.##", CultureInfo.InvariantCulture);

    System.Collections.Generic.List<string> lstFields = new System.Collections.Generic.List<string>();
    if (strCurCode != strOrigCode)
        lstFields.Add("Mã đáp án");
    if (strCurName != strOrigName)
        lstFields.Add("Nội dung");
    if (strCurQuestionID != strOrigQuestionID)
        lstFields.Add("Câu hỏi");
    if (strCurMark != strOrigMarkNorm)
        lstFields.Add("Điểm");

    return String.Join(", ", lstFields.ToArray());
}

